var g1 = Solution.BuildGetter(typeof(Person), "Age");
var g2 = Solution.BuildGetter(typeof(Person), "Age");
Cj.True(ReferenceEquals(g1, g2), "same (type,name) must return the SAME delegate instance");
var p = new Person { Name = "Ada", Age = 36 };
Cj.Eq((int?)g1(p), 36, "cached getter works");
Cj.Eq((string?)Solution.Read(p, "Name"), "Ada", "Read convenience");

var p = new Person { Name = "x", Age = 1 };
var getter = Solution.BuildGetter(typeof(Person), "Age");
for (int i = 0; i < 200; i++) getter(p);   // warm the reflection caches
long b0 = GC.GetAllocatedBytesForCurrentThread();
for (int i = 0; i < 50; i++) getter(p);
long b1 = GC.GetAllocatedBytesForCurrentThread();
// Calibrated on this runtime: one cached GetValue call on an int prop costs
// ~24 B (boxing + args array) - under 50*32 total. A closure that re-resolves
// GetProperty on every invoke exceeds 50*200.
Cj.True(b1 - b0 < 50 * 32, $"per-call overhead too high: {b1 - b0}");
